inline ::flatbuffers::Offset<TXSEmission> CreateTXSEmission(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Offset<::flatbuffers::String> EMISSION_ID = 0,
    double FREQUENCY_KHZ = 0.0,
    double BANDWIDTH_KHZ = 0.0,
    ::flatbuffers::Offset<::flatbuffers::String> EMISSION_DESIGNATOR = 0,
    txsModulationClass MODULATION = txsModulationClass_UNSPECIFIED,
    txsPolarization POLARIZATION = txsPolarization_UNSPECIFIED,
    txsServiceClass SERVICE = txsServiceClass_UNSPECIFIED,
    double TRANSMITTER_POWER_KW = 0.0,
    double EFFECTIVE_RADIATED_POWER_KW = 0.0,
    double EIRP_KW = 0.0,
    double ANTENNA_HEIGHT_AGL_M = 0.0,
    double ANTENNA_AZIMUTH_DEG = 0.0,
    bool OMNIDIRECTIONAL = false,
    double BEAMWIDTH_DEG = 0.0,
    double ANTENNA_GAIN_DBI = 0.0,
    ::flatbuffers::Offset<::flatbuffers::String> STATION_IDENTITY = 0,
    txsOperationalStatus STATUS = txsOperationalStatus_UNSPECIFIED,
    ::flatbuffers::Offset<::flatbuffers::String> VALID_FROM = 0,
    ::flatbuffers::Offset<::flatbuffers::String> VALID_UNTIL = 0) {
  TXSEmissionBuilder builder_(_fbb);
  builder_.add_ANTENNA_GAIN_DBI(ANTENNA_GAIN_DBI);
  builder_.add_BEAMWIDTH_DEG(BEAMWIDTH_DEG);
  builder_.add_ANTENNA_AZIMUTH_DEG(ANTENNA_AZIMUTH_DEG);
  builder_.add_ANTENNA_HEIGHT_AGL_M(ANTENNA_HEIGHT_AGL_M);
  builder_.add_EIRP_KW(EIRP_KW);
  builder_.add_EFFECTIVE_RADIATED_POWER_KW(EFFECTIVE_RADIATED_POWER_KW);
  builder_.add_TRANSMITTER_POWER_KW(TRANSMITTER_POWER_KW);
  builder_.add_BANDWIDTH_KHZ(BANDWIDTH_KHZ);
  builder_.add_FREQUENCY_KHZ(FREQUENCY_KHZ);
  builder_.add_VALID_UNTIL(VALID_UNTIL);
  builder_.add_VALID_FROM(VALID_FROM);
  builder_.add_STATION_IDENTITY(STATION_IDENTITY);
  builder_.add_EMISSION_DESIGNATOR(EMISSION_DESIGNATOR);
  builder_.add_EMISSION_ID(EMISSION_ID);
  builder_.add_STATUS(STATUS);
  builder_.add_OMNIDIRECTIONAL(OMNIDIRECTIONAL);
  builder_.add_SERVICE(SERVICE);
  builder_.add_POLARIZATION(POLARIZATION);
  builder_.add_MODULATION(MODULATION);
  return builder_.Finish();
}

